package com.aayushpuranik.jokesandmemesapp.views.viewModelsimport androidx.lifecycle.ViewModelimport com.aayushpuranik.jokesandmemesapp.HomeIntentimport com.aayushpuranik.jokesandmemesapp.Repository.JokesRepositoryimport com.aayushpuranik.jokesandmemesapp.models.JokeModelimport com.aayushpuranik.jokesandmemesapp.views.NetworkStateimport com.aayushpuranik.jokesandmemesapp.views.ui.HomeUIStateimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.launchimport javax.inject.Inject@HiltViewModelclass JokesViewModel @Inject constructor(    private val jokesRepository: JokesRepository): ViewModel() {    private val _homeState = MutableStateFlow(HomeUIState())    val homeState: StateFlow<HomeUIState>        get() = _homeState    private val mutableMap: MutableMap<String, List<JokeModel>> = mutableMapOf()    fun handleIntent(homeIntent: HomeIntent) {        _homeState.value = HomeUIState(true, null, null)        when(homeIntent) {            HomeIntent.LoadAllJokes -> fetchAllCategories()        }    }    private fun processIntent(intent: HomeIntent) {        val newState = reducer(_homeState.value, intent)        _homeState.value = newState    }    private fun reducer(state: HomeUIState, intent: HomeIntent): HomeUIState {        return when(intent) {            HomeIntent.LoadAllJokes -> state.copy(state.IsLoading, state.LoadAllJokes, state.ErrorMessage)        }    }    private fun fetchAllCategories() {        CoroutineScope(Dispatchers.IO).launch {            val response = jokesRepository.getJokes()            when(response) {                is NetworkState.Error -> {                    _homeState.value = HomeUIState(false, null, response.error)                    processIntent(HomeIntent.LoadAllJokes)                }                is NetworkState.Success -> {                    val groupedData = response.data?.groupBy { it.type }                    _homeState.value = HomeUIState(false, groupedData, null)                    processIntent(HomeIntent.LoadAllJokes)                }            }        }    }}